import { useEffect, useRef, useState } from 'react';
import type { GeneralResearch } from '../../../../evolver/src/contracts/general-research.ts';
import type { GeneralKnowledgeEntry } from '../../../../evolver/src/contracts/general-knowledge.ts';
import { WikiGraph, WIKI_TYPES } from './WikiGraph.tsx';
import { WikiBoard } from './WikiBoard.tsx';
import { WikiContent, WikiImages } from './WikiContent.tsx';
import { WikiEditor, WikiTools, WIKI_NATURES, type WikiAction } from './WikiTools.tsx';

export function KnowledgePanel({ general: g, researchId, kind, action, busy, inspect, sessionId }: { general: GeneralResearch; researchId: string; kind: GeneralKnowledgeEntry['kind']; action: WikiAction; busy: boolean; inspect: (id: string) => void; sessionId?: string }) {
  const [selected, setSelected] = useState<string | null>(null), [query, setQuery] = useState(''), [tab, setTab] = useState<'knowledge' | 'files'>('knowledge'), [representation, setRepresentation] = useState<'graph' | 'board'>('graph'), [detail, setDetail] = useState('summary'), [error, setError] = useState(''), [notice, setNotice] = useState(''), [editor, setEditor] = useState<'new' | 'edit' | null>(null), [tools, setTools] = useState(false), [directory, setDirectory] = useState(false), [details, setDetails] = useState(false);
  const [sourceBody, setSourceBody] = useState<{ text: string | null; image: boolean; coverage: string } | null>(null), [loading, setLoading] = useState(false), [to, setTo] = useState(''), [relationKind, setRelationKind] = useState('related'), [relationSource, setRelationSource] = useState(''), [quote, setQuote] = useState('');
  const [graphToolbar, setGraphToolbar] = useState<HTMLDivElement | null>(null);
  const upload = useRef<HTMLInputElement | null>(null), image = useRef<HTMLInputElement | null>(null), importOkf = useRef<HTMLInputElement | null>(null);
  const latest = g.knowledge.filter(e => e.kind === kind && !g.knowledge.some(n => n.entryId === e.entryId && n.version > e.version)), entries = latest.filter(e => !e.archived), item = latest.find(e => e.entryId === selected), source = g.sources.find(s => selected === `source:${s.sourceId}`);
  const allowed = (id: string) => g.sources.some(s => s.sourceId === id) && (g.sourceAccess.filter(a => a.sourceId === id).at(-1)?.allowed ?? true);
  const readable = (e: GeneralKnowledgeEntry) => [...e.sourceRefs, ...(e.images ?? []).map(i => i.sourceId), ...(e.claims ?? []).flatMap(c => c.locators.flatMap(l => l.kind === 'calculation' ? [g.calculations.find(c => c.calculationId === l.calculationId)?.input.sourceId ?? 'missing-source'] : [l.sourceId])), ...e.calculationIds.map(id => g.calculations.find(c => c.calculationId === id)?.input.sourceId ?? 'missing-source')].every(allowed);
  const sourceUrl = (id: string, inline = true) => `/evolver/research-bootstrap/source?${new URLSearchParams({ sessionId: sessionId ?? '', researchId, sourceId: id, ...(inline ? { inline: 'image' } : {}) })}`;
  const uri = (op: string, extra: Record<string, string> = {}) => `/evolver/research-bootstrap/wiki?${new URLSearchParams({ sessionId: sessionId ?? '', researchId, op, ...extra })}`;
  const read = async (op: string) => { if (!sessionId) throw new Error('需要工作台会话'); const r = await fetch(uri(op), { credentials: 'same-origin' }), b = await r.json(); if (!r.ok) throw new Error(b.message ?? b.error); return b; };
  const perform: WikiAction = async (type, payload) => { setError(''); try { const r = await action(type, { researchId, ...payload }); if (!r) throw new Error('操作未保存；请查看工作台错误和连接状态'); return r; } catch (e) { setError(String(e instanceof Error ? e.message : e)); return null; } };
  const select = (id: string) => { setSelected(id); setDetails(true); setDirectory(false); if (id.startsWith('source:')) { setTab('files'); setDetail('document'); } else setDetail('summary'); };
  const q = query.trim().toLowerCase(), filtered = entries.filter(e => `${e.title} ${e.category} ${readable(e) ? e.content : ''}`.toLowerCase().includes(q)), files = g.sources.filter(s => `${s.filename} ${s.description}`.toLowerCase().includes(q)), groups = [...new Set(entries.map(e => e.category))];
  const relations = g.knowledgeRelations.filter(r => r.fromEntryId === selected || r.toEntryId === selected);
  useEffect(() => {
    setSourceBody(null); setLoading(false); if (!source || !allowed(source.sourceId)) return;
    const controller = new AbortController(); setLoading(true);
    fetch(uri('source', { sourceId: source.sourceId }), { credentials: 'same-origin', signal: controller.signal }).then(async r => { const b = await r.json(); if (!r.ok) throw new Error(b.message ?? b.error); setSourceBody(b); }).catch(e => { if (!controller.signal.aborted) setError(String(e)); }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [selected, researchId, source?.sha256, JSON.stringify(g.sourceAccess)]);
  const encode = async (file: File) => { if (file.size > 24 * 1024 * 1024) throw new Error('文件超过 24 MiB'); const bytes = new Uint8Array(await file.arrayBuffer()); let s = ''; for (let i = 0; i < bytes.length; i += 8192) s += String.fromCharCode(...bytes.subarray(i, i + 8192)); return btoa(s); };
  const importFiles = async (list: FileList | null, picture = false) => {
    if (!list?.length) return; if (list.length > 15) { setError('每批最多 15 个文件，未静默截断'); return; }
    for (const f of Array.from(list)) { try { const saved = await perform('import_general_material', { filename: f.name, mediaType: f.type || (/\.(md|markdown|txt)$/i.test(f.name) ? 'text/plain' : 'application/octet-stream'), contentBase64: await encode(f), nature: 'unknown', description: picture ? '知识图片，人工上传' : 'Wiki 原始资料', purpose: '科研知识整理与引用' }); if (!saved) break;
      if (picture && item) { const { entryId: _, version: _v, createdAt: _at, ...entry } = item; if (!await perform('save_general_knowledge', { entryId: item.entryId, entry: { ...entry, images: [...(item.images ?? []), { sourceId: String(saved.sourceId), caption: f.name }] } })) break; }
      else select(`source:${saved.sourceId}`); setNotice(`${f.name} 已登记，尚未启动模型。`);
    } catch (e) { setError(String(e)); break; } }
  };
  const exportFile = async (op: 'okf' | 'json') => { try { let blob: Blob, name: string;
    if (op === 'okf') { const b = await read('okf'); blob = new Blob([Uint8Array.from(atob(b.contentBase64), c => c.charCodeAt(0))], { type: 'application/zip' }); name = b.filename; }
    else { const r = await fetch(`/evolver/research-bootstrap/knowledge-graph?${new URLSearchParams({ sessionId: sessionId ?? '', researchId })}`), b = await r.json(); if (!r.ok) throw new Error(b.message ?? b.error); blob = new Blob([JSON.stringify(b, null, 2)], { type: 'application/json' }); name = `wiki-${researchId}.json`; }
    const url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = name; a.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1500);
  } catch (e) { setError(String(e)); } };
  return <div className="wiki" data-wiki-kind={kind}>
    <div className="banner"><div><h1>LLM Wiki <span>/ 知识关系图谱</span></h1><p>从文献、实验和笔记中追踪概念与证据的来源</p></div><div className="banner-right"><span className="chip">{g.sources.length && g.sources.every(s => s.nature === 'simulation') ? 'simulation · 示例知识图谱' : '研究知识图谱'}</span><button className="action" onClick={() => void exportFile('json')}>↓ 导出 JSON</button><button className="action primary" disabled={busy} onClick={() => upload.current?.click()}>＋ 导入文档</button><button className="action" aria-label="知识整理与维护" onClick={() => setTools(true)}>⋯</button></div></div>
    <input hidden ref={upload} type="file" accept=".md,.markdown,.txt,.csv,.json,.xlsx" multiple onChange={e => { void importFiles(e.target.files); e.target.value = ''; }} /><input hidden ref={image} type="file" accept="image/png,image/jpeg,image/gif,image/webp" onChange={e => { void importFiles(e.target.files, true); e.target.value = ''; }} /><input hidden ref={importOkf} type="file" accept=".zip" onChange={async e => { const f = e.target.files?.[0]; e.target.value = ''; if (f) { try { await perform('import_general_wiki_okf', { contentBase64: await encode(f) }); } catch (e) { setError(String(e)); } } }} />
    {(error || notice) && <div className={`wiki-feedback${error ? ' error' : ''}`} role={error ? 'alert' : 'status'}>{error || notice}<button aria-label="关闭提示" onClick={() => { setError(''); setNotice(''); }}>×</button></div>}
    <div className="workspace"><aside className={`left${directory ? ' mobile-open' : ''}`} aria-label="知识目录"><div className="left-tabs"><button aria-pressed={tab === 'knowledge'} className={tab === 'knowledge' ? 'active' : ''} onClick={() => setTab('knowledge')}>Knowledge</button><button aria-pressed={tab === 'files'} className={tab === 'files' ? 'active' : ''} onClick={() => setTab('files')}>Files</button><button className="mobile-detail" onClick={() => setDirectory(false)}>关闭</button></div><div className="filterbar"><div className="search"><span>⌕</span><input aria-label="搜索实体、文档" placeholder="搜索实体、论文或方法…" value={query} onChange={e => setQuery(e.target.value)} /></div><div className="result">{tab === 'knowledge' ? `实体 · ${filtered.length} / ${entries.length}` : `文件 · ${files.length} / ${g.sources.length}`}</div></div>
      <div className="left-scroll">{tab === 'knowledge' ? groups.map(category => { const es = filtered.filter(e => e.category === category); return !es.length ? null : <section key={category}><div className="groupcap">{category}<b>{es.length}</b></div>{es.map(e => <button key={e.entryId} className={`row-entry${selected === e.entryId ? ' active' : ''}`} title={e.title} onClick={() => select(e.entryId)}><span className="type-dot" style={{ background: WIKI_TYPES[e.entityType ?? 'concept'].color }} /><span className="label">{e.title}</span></button>)}</section>; }) : files.map(s => <button key={s.sourceId} className={`row-entry${source?.sourceId === s.sourceId ? ' active' : ''}`} onClick={() => select(`source:${s.sourceId}`)}><span className="fileicon">▤</span><span className="label">{s.filename}</span>{!allowed(s.sourceId) && <small>撤权</small>}</button>)}{!(tab === 'knowledge' ? filtered.length : files.length) && <p className="empty">没有匹配结果</p>}{latest.some(e => e.archived) && <details><summary>已归档</summary>{latest.filter(e => e.archived).map(e => <button key={e.entryId} className="row-entry" onClick={() => { setSelected(e.entryId); setEditor('edit'); }}>{e.title} · 编辑恢复</button>)}</details>}</div><div className="footinfo">后端保存 · 版本与来源可追溯</div></aside>
      <section className="graph-col" aria-label={representation === 'graph' ? '知识图谱' : '知识白板'}><div className="graph-top"><div className="graph-title"><strong>{representation === 'graph' ? 'Knowledge Graph' : 'Knowledge Board'}</strong><small>{entries.length + g.sources.length} nodes</small></div><div ref={setGraphToolbar} style={{display:representation === 'graph' ? 'block' : 'none'}} className="wiki-graph-toolbar" /></div>
        <div style={{ display: representation === 'graph' ? 'flex' : 'none', flex: 1, minHeight: 0 }}><WikiGraph openDetails={() => setDetails(true)} toolbar={graphToolbar} general={g} entries={entries} selected={selected} select={select} query={query} save={async positions => !!await perform('save_general_knowledge_layout', { positions })} /></div><div style={{ display: representation === 'board' ? 'flex' : 'none', flex: 1, minHeight: 0 }}><WikiBoard readable={readable} boards={g.wiki?.boards ?? []} entries={entries} selected={item?.entryId ?? null} select={select} persist={async board => !!await perform('save_general_wiki_board', { board })} busy={busy} sourceUrl={sourceUrl} allowed={allowed} /></div>
        <div className="graph-footer"><div className="tabs" aria-label="知识表示"><button className="mobile-directory" onClick={() => setDirectory(true)}>目录</button><button className={representation === 'graph' ? 'active' : ''} aria-pressed={representation === 'graph'} onClick={() => setRepresentation('graph')}>关系图谱</button><button className={representation === 'board' ? 'active' : ''} aria-pressed={representation === 'board'} onClick={() => setRepresentation('board')}>知识白板</button><button className="mobile-detail" onClick={() => setDetails(true)}>详情</button></div><span>研究知识图谱 · {g.sources.every(s => s.nature === 'simulation') && g.sources.length ? 'simulation' : '后端持久保存'}</span><span><strong>{item?.title ?? source?.filename ?? '未选择'}</strong><button onClick={() => setEditor('new')}>＋ 新建实体</button></span></div></section>
      <aside className={`right${details ? ' mobile-open' : ''}`} aria-label="文档与实体详情"><div className="doc-head"><div className="doc-overline"><span>{source ? 'SOURCE DOCUMENT' : 'NODE INSPECTOR'}</span><button className="mobile-detail" onClick={() => setDetails(false)}>关闭详情</button></div><h2>{item?.title ?? source?.filename ?? '研究知识图谱'}</h2><p>{item ? `${item.category} · v${item.version}` : source ? `来源 v${source.revision}` : '点击图谱节点查看实体、关联和来源文档。'}</p><div className="doc-tags">{item && <><span>{WIKI_TYPES[item.entityType ?? 'concept'].label}</span><span>{WIKI_NATURES[item.nature]}</span></>}</div></div><div className="right-tabs">{['summary', 'document', 'relations'].map(t => <button key={t} aria-pressed={detail === t} className={detail === t ? 'active' : ''} onClick={() => setDetail(t)}>{t === 'summary' ? '概览' : t === 'document' ? '文档预览' : '关联'}</button>)}</div>
        <div className="doc-content">{source ? !allowed(source.sourceId) ? <p>来源已撤权，正文与图片不再读取。</p> : <>{loading && <p role="status">读取原始资料…</p>}{sourceBody?.text != null && <WikiContent text={sourceBody.text} select={select} />}{sourceBody?.image && <img className="source-image" src={sourceUrl(source.sourceId)} alt={source.filename} />}<p>{sourceBody?.coverage}</p><a href={sourceUrl(source.sourceId, false)}>下载原始文件 ↗</a><h3>引用此资料的知识</h3>{entries.filter(e => e.sourceRefs.includes(source.sourceId)).map(e => <button key={e.entryId} className="linked" onClick={() => select(e.entryId)}>{e.title}</button>)}</> : !item ? <p>选择知识以查看正文、来源和关联。</p> : !readable(item) ? <p>知识依赖已撤权来源，暂不可读；历史记录保留。</p> : detail === 'summary' ? <><h3>知识实体概览</h3><WikiContent text={item.content} select={select} /><WikiImages entry={item} sourceUrl={sourceUrl} allowed={allowed} expand />{([['适用条件', item.conditions], ['反证与分歧', item.counterEvidence], ['限制与未知', item.limitations]] as [string, string[] | undefined][]).map(([title, lines]) => !lines?.length ? null : <section key={title}><h3>{title}</h3>{lines.map((s, i) => <p key={i}>{s}</p>)}</section>)}<div className="subnote">{WIKI_NATURES[item.nature]}；关联不代表科学支持。</div><div className="flex"><button className="action" onClick={() => setEditor('edit')}>编辑 v{item.version}</button><button className="action" disabled={busy} onClick={() => image.current?.click()}>添加图片</button></div><h3>相关来源</h3>{item.sourceRefs.map(id => <button className="linked" key={id} onClick={() => select(`source:${id}`)}>▤ {g.sources.find(s => s.sourceId === id)?.filename ?? '来源缺失'}<small>查看预览 ↗</small></button>)}</> : detail === 'document' ? <><h3>来源与定位</h3>{item.sourceRefs.map(id => <button className="linked" key={id} onClick={() => select(`source:${id}`)}>{g.sources.find(s => s.sourceId === id)?.filename} ↗</button>)}{!item.sourceRefs.length && <p>尚无来源，保持待核对。</p>}{(item.claims ?? []).map(c => <section key={c.claimId}><h4>{c.text}</h4><p>{c.limitation}</p>{c.locators.map((l, i) => <div key={i}>{l.kind === 'text' ? <><blockquote>{l.quote}</blockquote><button className="link" onClick={() => select(`source:${l.sourceId}`)}>原文 bytes {l.startByte}–{l.endByte} ↗</button></> : <p>{l.kind === 'table' ? `表格第 ${l.row + 1} 行` : l.kind === 'pdf' ? `PDF 第 ${l.page} 页：${l.quote}` : `计算产物 ${l.calculationId}`}</p>}</div>)}</section>)}<details><summary>历史版本</summary>{g.knowledge.filter(e => e.entryId === item.entryId).map(e => <section key={e.version}><h4>v{e.version} · {e.createdAt}</h4><WikiContent text={e.content} select={select} /></section>)}</details></> : <><h3>直接关联 · {relations.length}</h3>{relations.map(r => { const id = r.fromEntryId === item.entryId ? r.toEntryId : r.fromEntryId; return <button className="linked" key={r.relationId} onClick={() => select(id)}>{entries.find(e => e.entryId === id)?.title ?? '归档知识'}<small>{r.kind === 'related' ? '人工关联' : '证据关联'}</small></button>; })}<h4>新建人工关系</h4><select aria-label="关联目标" value={to} onChange={e => setTo(e.target.value)}><option value="">选择知识</option>{entries.filter(e => e.entryId !== selected).map(e => <option key={e.entryId} value={e.entryId}>{e.title}</option>)}</select><select aria-label="关系性质" value={relationKind} onChange={e => setRelationKind(e.target.value)}><option value="related">人工关联</option><option value="evidence_for">证据关联（需原文）</option></select>{relationKind === 'evidence_for' && <><select aria-label="证据来源" value={relationSource} onChange={e => setRelationSource(e.target.value)}><option value="">选择来源</option>{g.sources.filter(s => allowed(s.sourceId)).map(s => <option key={s.sourceId} value={s.sourceId}>{s.filename}</option>)}</select><textarea aria-label="原文引用" value={quote} onChange={e => setQuote(e.target.value)} placeholder="精确原文" /></>}<button className="action" disabled={busy || !to} onClick={async () => { if (await perform('save_general_knowledge_relation', { relation: { fromEntryId: item.entryId, toEntryId: to, kind: relationKind, note: relationKind === 'related' ? '人工关联，不代表科学支持' : '人工登记的原文证据关联', locator: relationKind === 'evidence_for' ? { kind: 'text', sourceId: relationSource, quote } : null } })) setTo(''); }}>保存关系</button>{item.nodeIds.map(id => <button className="linked" key={id} onClick={() => inspect(id)}>{g.graph.nodes.find(n => n.nodeId === id)?.title} →</button>)}</>}</div></aside>
    </div>
    {editor && <WikiEditor general={g} entry={editor === 'edit' ? item : undefined} kind={kind} close={() => setEditor(null)} save={async (type, payload) => { const r = await perform(type, payload); if (r) select(String(r.entryId)); return r; }} />}
    {tools && <WikiTools general={g} action={perform} read={read} select={select} close={() => setTools(false)} exportOkf={() => void exportFile('okf')} importOkf={() => importOkf.current?.click()} />}
  </div>;
}
