import { useEffect, useMemo, useRef, useState, type PointerEvent } from 'react';
import { knowledgeNetworkLayout, type KnowledgeNetwork, type KnowledgeNode, type KnowledgeRelationKind } from './knowledge-network.ts';
import { StudioIcon as Icon, type Positions } from './StudioCanvas.tsx';
const RELATIONS: Record<KnowledgeRelationKind,string>={source:'来源引用',wikilink:'页面互链',related:'条目关联',evidence:'已登记证据'};
const TYPES: Record<string,string>={knowledge:'知识条目',method:'研究方法',source:'原始来源',entity:'实体',concept:'概念',overview:'综述',metric:'指标',experiment:'实验记录'};
export function StudioKnowledgeGraph(props:{network:KnowledgeNetwork;selected:string|null;select:(id:string|null)=>void;query:string;initialPositions?:Positions;persistIds:string[];onPersist?:(positions:Positions)=>Promise<boolean>}){
 const [camera,setCamera]=useState({x:0,y:0,k:1}),[draft,setDraft]=useState<Positions>({}),[filter,setFilter]=useState('all'),[neighborhood,setNeighborhood]=useState(false),[showSources,setShowSources]=useState(true),[showLinks,setShowLinks]=useState(true),[notice,setNotice]=useState(''),[pending,setPending]=useState<Positions>({}),[busy,setBusy]=useState(false);
 const svg=useRef<SVGSVGElement|null>(null),gesture=useRef<{id:string|null;px:number;py:number;x:number;y:number;moved:boolean}|null>(null);
 const topology=JSON.stringify([props.network.nodes.map(n=>n.id),props.network.edges.map(e=>[e.from,e.to])]);
 const layout=useMemo(()=>knowledgeNetworkLayout(props.network.nodes,props.network.edges),[topology]);
 const positions=Object.fromEntries(props.network.nodes.map(n=>[n.id,draft[n.id]??props.initialPositions?.[n.id]??layout[n.id]]));
 const current=useRef(positions);current.current=positions;
 const query=props.query.trim().toLowerCase();
 const neighbors=new Set(props.network.edges.filter(e=>e.from===props.selected||e.to===props.selected).flatMap(e=>[e.from,e.to]));
 const nodes=props.network.nodes.filter(n=>(filter==='all'||n.type===filter)&&(!neighborhood||!props.selected||n.id===props.selected||neighbors.has(n.id)));
 const visible=new Set(nodes.map(n=>n.id));
 const edges=props.network.edges.filter(e=>visible.has(e.from)&&visible.has(e.to)&&(e.kind==='source'?showSources:showLinks));
 const degree=(id:string)=>props.network.edges.filter(e=>e.from===id||e.to===id).length;
 const fit=()=>{const ps=nodes.map(n=>current.current[n.id]);if(!ps.length)return;const minX=Math.min(...ps.map(p=>p.x))-125,maxX=Math.max(...ps.map(p=>p.x))+125,minY=Math.min(...ps.map(p=>p.y))-65,maxY=Math.max(...ps.map(p=>p.y))+65,k=Math.min(1.7,1060/(maxX-minX),630/(maxY-minY));setCamera({k,x:590-(minX+maxX)/2*k,y:380-(minY+maxY)/2*k});};
 useEffect(()=>{fit();},[topology,filter,neighborhood]);
 const point=(e:{clientX:number;clientY:number})=>{const r=svg.current!.getBoundingClientRect(),scale=Math.min(r.width/1180,r.height/760)||1;return{x:(e.clientX-r.left-(r.width-1180*scale)/2)/scale,y:(e.clientY-r.top-(r.height-760*scale)/2)/scale};};
 const save=async(values:Positions)=>{const persisted=Object.fromEntries(Object.entries(values).filter(([id])=>props.persistIds.includes(id)));if(!props.onPersist||!Object.keys(persisted).length){setNotice('布局已调整 · 仅本次视图');return;}setBusy(true);setNotice('正在保存图谱布局…');try{const ok=await props.onPersist(persisted);setNotice(ok?'图谱布局已保存':'布局未保存 · 可重试');setPending(ok?{}:persisted);}catch(e){setPending(persisted);setNotice(`布局未保存：${e instanceof Error?e.message:String(e)}`);}finally{setBusy(false);}};
 const down=(e:PointerEvent<SVGSVGElement>)=>{if(e.button!==0||busy)return;const id=(e.target as Element).closest('[data-knowledge-node]')?.getAttribute('data-knowledge-node')??null,p=point(e),start=id?positions[id]:camera;gesture.current={id,px:p.x,py:p.y,x:start.x,y:start.y,moved:false};e.currentTarget.setPointerCapture(e.pointerId);};
 const move=(e:PointerEvent<SVGSVGElement>)=>{const g=gesture.current;if(!g)return;const p=point(e),dx=p.x-g.px,dy=p.y-g.py;if(Math.abs(dx)+Math.abs(dy)<4&&!g.moved)return;g.moved=true;if(g.id){const next={x:g.x+dx/camera.k,y:g.y+dy/camera.k};current.current={...current.current,[g.id]:next};setDraft(v=>({...v,[g.id!]:next}));}else setCamera(c=>({...c,x:g.x+dx,y:g.y+dy}));};
 const up=()=>{const g=gesture.current;gesture.current=null;if(!g)return;if(g.id){props.select(g.id);if(g.moved)void save({[g.id]:current.current[g.id]});}else if(!g.moved)props.select(null);};
 const label=(n:KnowledgeNode)=>{const chars=Array.from(n.title),limit=props.selected===n.id?70:42;return chars.slice(0,limit).join('')+(chars.length>limit?'…':'');};
 return <section className="studio-knowledge-network" aria-label="Wiki 知识关系图谱">
 <div className="knowledge-graph-tools"><div><strong>Knowledge Graph</strong><span>{props.network.nodes.length} 节点 · {props.network.edges.length} 关系</span></div><div className="knowledge-filters"><label>类型<select aria-label="筛选知识节点类型" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">全部类型</option>{[...new Set(props.network.nodes.map(n=>n.type))].map(t=><option key={t} value={t}>{TYPES[t]??t}</option>)}</select></label><label><input type="checkbox" checked={showSources} onChange={e=>setShowSources(e.target.checked)}/>来源引用</label><label><input type="checkbox" checked={showLinks} onChange={e=>setShowLinks(e.target.checked)}/>页面关联</label><label><input type="checkbox" checked={neighborhood} onChange={e=>setNeighborhood(e.target.checked)}/>只看邻域</label></div></div>
 <div className="knowledge-graph-stage"><svg ref={svg} viewBox="0 0 1180 760" aria-label="Wiki 节点与关联网络" onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={()=>{gesture.current=null;}} onWheel={e=>{const p=point(e),k=Math.min(3,Math.max(.15,camera.k*(e.deltaY<0?1.12:.9)));setCamera({k,x:p.x-(p.x-camera.x)*k/camera.k,y:p.y-(p.y-camera.y)*k/camera.k});}}>
 <g transform={`translate(${camera.x},${camera.y}) scale(${camera.k})`}>
 {edges.map(e=>{const a=positions[e.from],b=positions[e.to],active=e.from===props.selected||e.to===props.selected;return <line data-knowledge-edge={e.kind} key={e.id} x1={a.x} y1={a.y} x2={b.x} y2={b.y} className={`knowledge-edge ${e.kind}${e.available===false?' unavailable':''}${active?' active':props.selected?' dim':''}`}><title>{RELATIONS[e.kind]} · {e.label}</title></line>;})}
 {nodes.map(n=>{const p=positions[n.id],active=n.id===props.selected,dim=!!query?!`${n.title} ${n.category}`.toLowerCase().includes(query):!!props.selected&&!active&&!neighbors.has(n.id);return <g key={n.id} role="button" tabIndex={0} aria-label={`${n.title} · ${TYPES[n.type]??n.type} · ${degree(n.id)} 条关系`} aria-pressed={active} data-knowledge-node={n.id} className={`knowledge-point ${n.type}${active?' selected':''}${dim?' dim':''}${!n.readable?' revoked':''}`} transform={`translate(${p.x},${p.y})`} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();props.select(n.id);}if(e.altKey&&e.key.startsWith('Arrow')){e.preventDefault();const next={x:p.x+(e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0),y:p.y+(e.key==='ArrowDown'?20:e.key==='ArrowUp'?-20:0)};setDraft(v=>({...v,[n.id]:next}));void save({[n.id]:next});}}}><rect className="knowledge-hitbox" x={-Math.min(190,Math.max(50,label(n).length*4.5))} y={-28} width={Math.min(380,Math.max(100,label(n).length*9))} height={76} rx={12}/><title>{n.title} · {TYPES[n.type]??n.type} · {n.version}{!n.readable?' · 来源不可读':''}</title><circle r={Math.min(21,8+Math.sqrt(degree(n.id))*2.2)+(active?3:0)}/><text y={31} textAnchor="middle">{label(n)}</text></g>;})}
 </g></svg>
 {!nodes.length&&<div className="canvas-empty"><Icon name="network"/><h3>没有匹配的知识节点</h3><p>导入资料或调整筛选条件。</p></div>}
 <div className="knowledge-legend"><span><i/>知识条目</span><span><i className="source"/>原始来源</span><span className="line-key">实线：页面互链 / 登记关系</span><span className="line-key dashed">虚线：来源引用</span><small>共同来源展示为共享来源节点；不代表条目相互支持。</small></div>
 <div className="canvas-tools"><button aria-label="缩小知识图谱" onClick={()=>setCamera(c=>({...c,k:Math.max(.15,c.k/1.2)}))}><Icon name="zoom-out"/></button><span className="zoom-num">{Math.round(camera.k*100)}%</span><button aria-label="放大知识图谱" onClick={()=>setCamera(c=>({...c,k:Math.min(3,c.k*1.2)}))}><Icon name="zoom-in"/></button><button aria-label="适应知识图谱视野" onClick={fit}><Icon name="fit"/></button><button aria-label="按关联重排图谱" disabled={busy} onClick={()=>{setDraft(layout);current.current=layout;fit();void save(layout);}}><Icon name="refresh"/></button><button aria-label="清除图谱选择" onClick={()=>props.select(null)}><Icon name="x"/></button></div>
 {notice&&<div className="canvas-save" role="status">{notice}{Object.keys(pending).length>0&&<button disabled={busy} onClick={()=>void save(pending)}>重试保存</button>}</div>}
 </div><div className="knowledge-graph-footer"><span>拖动节点 / 平移 · 滚轮缩放 · 点击高亮邻居</span><span>{props.network.broken.length?`${props.network.broken.length} 条未解析页面链接`:'显示已登记关系与来源，不按标题猜关联'}</span></div>
 </section>;
}
