import { createPortal } from 'react-dom';
import { useRef, useState, type PointerEvent } from 'react';
import type { GeneralResearch } from '../../../../evolver/src/contracts/general-research.ts';
import type { GeneralKnowledgeEntry } from '../../../../evolver/src/contracts/general-knowledge.ts';
export const WIKI_TYPES: Record<string, { label: string; color: string }> = { entity: { label: 'Entity', color: '#5194d9' }, concept: { label: 'Concept', color: '#a978dc' }, source: { label: 'Source', color: '#ef9752' }, overview: { label: 'Overview', color: '#94a7b8' }, metric: { label: 'Metric', color: '#e2b83b' }, experiment: { label: 'Experiment', color: '#53a48e' } };
export function WikiGraph({ general: g, entries, selected, select, query, save, toolbar, openDetails }: { general: GeneralResearch; entries: GeneralKnowledgeEntry[]; selected: string | null; select: (id: string) => void; query: string; toolbar?: HTMLElement | null; openDetails?: () => void; save: (positions: Record<string, { x: number; y: number }>) => Promise<boolean> }) {
  const [mode, setMode] = useState('type'), [camera, setCamera] = useState({ x: 0, y: 0, scale: 1 }), [draft, setDraft] = useState<Record<string, { x: number; y: number }>>({});
  const svg = useRef<SVGSVGElement | null>(null), gesture = useRef<{ id?: string; start: DOMPoint; x: number; y: number; moved: boolean } | null>(null), last = useRef<Record<string, { x: number; y: number }>>({});
  const nodes = [...entries.map(e => ({ id: e.entryId, title: e.title, type: e.entityType ?? 'concept', category: e.category })), ...g.sources.map(s => ({ id: `source:${s.sourceId}`, title: s.filename, type: 'source', category: '来源' }))];
  const edges = [...g.knowledgeRelations.filter(r => entries.some(e => e.entryId === r.fromEntryId) && entries.some(e => e.entryId === r.toEntryId)).map(r => ({ id: r.relationId, from: r.fromEntryId, to: r.toEntryId, label: r.note, evidence: r.kind === 'evidence_for' })), ...entries.flatMap(e => e.sourceRefs.filter(id => g.sources.some(s => s.sourceId === id)).map(id => ({ id: `${e.entryId}:${id}`, from: e.entryId, to: `source:${id}`, label: '文件级来源引用', evidence: false })))];
  const initial = (i: number) => ({ x: 590 + Math.cos(i * 2.399963) * (100 + Math.sqrt(i) * 45), y: 380 + Math.sin(i * 2.399963) * (80 + Math.sqrt(i) * 32) });
  const norm = (p: { x: number; y: number }) => ({ x: Math.round(Math.max(0, Math.min(100000, (p.x - 80) / 1020 * 100000))), y: Math.round(Math.max(0, Math.min(100000, (p.y - 70) / 620 * 100000))) });
  const positions = Object.fromEntries(nodes.map((n, i) => { const p = draft[n.id] ?? g.knowledgeLayout[n.id]; return [n.id, p ? { x: 80 + p.x / 100000 * 1020, y: 70 + p.y / 100000 * 620 } : initial(i)]; }));
  const degree = (id: string) => edges.filter(e => e.from === id || e.to === id).length;
  const neighbors = new Set(edges.filter(e => e.from === selected || e.to === selected).flatMap(e => [e.from, e.to]));
  const groups = [...new Set(nodes.map(n => n.category))], groupColor = (s: string) => ['#5194d9', '#a978dc', '#53a48e', '#e2b83b', '#ef9752'][groups.indexOf(s) % 5];
  const point = (e: { clientX: number; clientY: number }) => new DOMPoint(e.clientX, e.clientY).matrixTransform(svg.current!.getScreenCTM()!.inverse());
  const down = (e: PointerEvent<SVGSVGElement>) => { if (e.button !== 0) return; e.currentTarget.setPointerCapture(e.pointerId); gesture.current = { id: (e.target as Element).closest('[data-node]')?.getAttribute('data-node') ?? undefined, start: point(e), x: camera.x, y: camera.y, moved: false }; };
  const move = (e: PointerEvent<SVGSVGElement>) => { const p = gesture.current; if (!p) return; const pt = point(e); if (Math.abs(pt.x - p.start.x) + Math.abs(pt.y - p.start.y) > 3) p.moved = true; if (p.id) { const next = { ...draft, [p.id]: norm({ x: (pt.x - camera.x) / camera.scale, y: (pt.y - camera.y) / camera.scale }) }; last.current = next; setDraft(next); } else setCamera({ ...camera, x: p.x + pt.x - p.start.x, y: p.y + pt.y - p.start.y }); };
  const up = async () => { const p = gesture.current; gesture.current = null; if (p?.id) { if (p.moved) await save({ [p.id]: last.current[p.id] }); else select(p.id); } };
  const controls = <div className="graph-mode-tabs tabs" aria-label="图谱视图">{['type', 'community', 'insights'].map(m => <button key={m} aria-pressed={mode === m} className={mode === m ? 'active' : ''} onClick={() => setMode(m)}>{m === 'type' ? '◉ Type' : m === 'community' ? '▧ Community' : '✧ Insights'}</button>)}<button style={{padding:7}} aria-label="重排图谱" onClick={async () => { const ps = Object.fromEntries(nodes.map((n, i) => [n.id, norm(initial(i))])); setDraft(ps); await save(ps); }}>↻</button></div>;
  return <div className="graph-area">{toolbar ? createPortal(controls, toolbar) : controls}
    <svg ref={svg} viewBox="0 0 1180 760" aria-label="研究知识关系图" onPointerDown={down} onPointerMove={move} onPointerUp={() => void up()} onPointerCancel={() => { gesture.current = null; }} onWheel={e => { const p = point(e), scale = Math.max(.45, Math.min(2.8, camera.scale * (e.deltaY > 0 ? .9 : 1.1))); setCamera({ scale, x: p.x - (p.x - camera.x) / camera.scale * scale, y: p.y - (p.y - camera.y) / camera.scale * scale }); }}><g transform={`translate(${camera.x},${camera.y}) scale(${camera.scale})`}>
    <g>{edges.map(e => { const a = positions[e.from], b = positions[e.to], active = e.from === selected || e.to === selected; return <line key={e.id} className={`edge${active ? ' highlight' : selected ? ' dim' : ''}`} x1={a.x} y1={a.y} x2={b.x} y2={b.y} strokeDasharray={e.evidence ? undefined : '4 4'}><title>{e.label}</title></line>; })}</g>
    <g>{nodes.map(n => { const p = positions[n.id], dim = query ? !`${n.title} ${n.category}`.toLowerCase().includes(query.toLowerCase()) : selected && n.id !== selected && !neighbors.has(n.id); return <g key={n.id} data-node={n.id} transform={`translate(${p.x},${p.y})`} role="button" aria-label={n.title} tabIndex={0} className={`gnode${n.id === selected ? ' selected' : ''}${dim ? ' dim' : ''}`} onKeyDown={e => { if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); select(n.id); } }}><circle r={(n.type === 'overview' ? 11 : n.type === 'source' ? 8 : n.type === 'experiment' ? 10 : 9) + (n.id === selected ? 3 : 0)} fill={mode === 'community' ? groupColor(n.category) : WIKI_TYPES[n.type].color} /><text x={(n.type === 'overview' ? 11 : n.type === 'source' ? 8 : n.type === 'experiment' ? 10 : 9) + 6} y={4}>{n.title}</text></g>; })}</g></g></svg>
    <div className="controls"><button aria-label="放大" onClick={() => setCamera(v => ({ ...v, scale: Math.min(2.8, v.scale * 1.2) }))}>+</button><button aria-label="缩小" onClick={() => setCamera(v => ({ ...v, scale: Math.max(.45, v.scale / 1.2) }))}>−</button><button aria-label="适应窗口" onClick={() => { const ps = Object.values(positions); if (!ps.length) return; const minX = Math.min(...ps.map(p => p.x)), maxX = Math.max(...ps.map(p => p.x)), minY = Math.min(...ps.map(p => p.y)), maxY = Math.max(...ps.map(p => p.y)), scale = Math.min(1.5, 1000 / Math.max(300, maxX - minX), 620 / Math.max(300, maxY - minY)); setCamera({ scale, x: 590 - (minX + maxX) / 2 * scale, y: 380 - (minY + maxY) / 2 * scale }); }}>⌗</button><button className="mobile-detail" aria-label="查看详情" onClick={openDetails}>☰</button></div>
    <div className="corner"><h3>{mode === 'community' ? 'CATEGORY GROUPS' : 'NODE TYPES'}</h3><div className="legend">{mode === 'community' ? groups.map(c => <span key={c}><i style={{ background: groupColor(c) }} />{c}</span>) : Object.entries(WIKI_TYPES).map(([k, t]) => <span key={k}><i style={{ background: t.color }} />{t.label}</span>)}</div><small>{mode === 'community' ? '按分类分组，未运行自动聚类' : '滚轮缩放 · 拖动平移 · 点击节点'}</small></div>
    {mode === 'insights' && <div className="graph-pop"><h3>图谱统计（全图）</h3>{Object.entries(WIKI_TYPES).map(([k, t]) => <div className="statrow" key={k}><span>{t.label}</span><b>{nodes.filter(n => n.type === k).length}</b></div>)}<h4>高连接节点</h4>{[...nodes].sort((a, b) => degree(b.id) - degree(a.id)).slice(0, 6).map(n => <button key={n.id} className="insightlink" onClick={() => { select(n.id); setMode('type'); }}>{n.title}<b>{degree(n.id)}</b></button>)}</div>}
    {!nodes.length && <div className="board-empty"><h3>建立你的知识网络</h3><p>导入资料，或新建知识；原始资料和派生知识分别保存。</p></div>}
  </div>;
}
