 const [runDetails,setRunDetails]=useState(false);
 const runTrigger=useRef<HTMLButtonElement|null>(null);
 const [treeQuery,setTreeQuery]=useState(''),[dirty,setDirty]=useState(false);
 const [query,setQuery]=useState(''),[selected,setSelected]=useState<string|null>(null),[selectedNode,setSelectedNode]=useState<string|null>(null);
 const [directory,setDirectory]=useState(false),[tools,setTools]=useState(false),[mobileNav,setMobileNav]=useState(false),[showCandidates,setShowCandidates]=useState(false);
