 const revisionScope=useRef(scope);
 if(revisionScope.current!==scope){revisionScope.current=scope;revision.current=props.read?.bootstrap.revision??0;}else revision.current=Math.max(revision.current,props.read?.bootstrap.revision??0);
 useEffect(()=>{setRunDetails(false);setSelected(null);setSelectedNode(null);setError('');setNotice('');setModal(null);setQuery('');setTreeQuery('');setDirty(false);setDirectory(false);setShowCandidates(false);retry.current=null;},[scope]);
 useEffect(()=>{if(modal)dialog.current?.showModal();},[modal]);
 const openTools=()=>setTools(true);
 const go=(p:Page)=>{setRunDetails(false);setPage(p);setMobileNav(false);};
 async function action(type:string,payload:Record<string,unknown>={}) {
  if(lock.current||!research||!props.read)return null;
  lock.current=true;setBusy(true);setError('');setNotice('正在提交…');
  const key=JSON.stringify({type,...payload});if(retry.current?.payload!==key)retry.current={payload:key,id:newOperationId('studio')};
  try{const response=await fetch(`/evolver/research-bootstrap/actions?sessionId=${encodeURIComponent(props.sessionId)}`,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({type,researchId:research.researchId,baseRevision:revision.current,operationId:retry.current.id,...payload})});
   const body=await response.json();if(!response.ok||!body.ok)throw new Error(body.reason??body.message??body.error??`HTTP ${response.status}`);
   if(typeof body.revision==='number')revision.current=Math.max(revision.current,body.revision);
   setNotice(body.message??(body.state==='queued'?'已排队，等待产物':'已保存'));retry.current=null;try{await props.refresh();}catch(refreshError){setError(`写入已成功，但重新读取失败：${refreshError instanceof Error?refreshError.message:String(refreshError)}。请重新同步。`);}return body;
  }catch(e){setError(e instanceof Error?e.message:String(e));setNotice('');return null;}finally{lock.current=false;setBusy(false);}
 }
