 const selectedCard=data.cards.find(c=>c.id===selected), candidatesVisible=data.candidates.length>0&&(!data.nodes.length||showCandidates);
 const shownNodes=candidatesVisible?data.candidates:data.nodes,node=shownNodes.find(n=>n.id===selectedNode);
