 const knowledgePositions=g?Object.fromEntries(Object.entries(g.knowledgeLayout).map(([id,p])=>[id,{x:80+p.x/100000*1020,y:70+p.y/100000*620}])):undefined;
 const treePositions=Object.fromEntries(data.nodes.filter(n=>n.x!==undefined&&n.y!==undefined).map(n=>[n.id,{x:n.x!,y:n.y!}]));
 const generalEntries=g?.knowledge.filter(e=>!e.archived&&!g.knowledge.some(n=>n.entryId===e.entryId&&n.version>e.version))??[];
 const selectedEntry=generalEntries.find(e=>e.entryId===selected);
 const selectedSource=data.network.nodes.find(n=>n.id===selected&&n.type==='source');
 const knowledgeRelations=data.network.edges.filter(e=>e.from===selected||e.to===selected).filter((e,index,links)=>e.kind!=='related'||links.findIndex(other=>other.kind==='related'&&(other.from===selected?other.to:other.from)===(e.from===selected?e.to:e.from))===index);
 const relationLabel=(kind:string)=>({source:'来源引用',wikilink:'页面互链',related:'条目关联',evidence:'已登记证据'}[kind]??kind);
 const knowledgeGroups=[...new Set(cards.map(c=>c.category??c.kind))];
 const selectKnowledge=(target:string)=>{setSelected(data.network.nodes.some(n=>n.id===target)?target:resolveKnowledgeTarget(target,data.cards));setDirectory(false);};
 const linkedBody=selectedCard?.body.replace(/\[\[([^\]\n]+)\]\]/g,(raw,link:string)=>{const [target,alias]=link.split('|');const id=resolveKnowledgeTarget(target,data.cards);return id?`[${alias??target}](wiki:${id})`:raw;})??'';
 const exportIndex=()=>{const url=URL.createObjectURL(new Blob([knowledgeIndexMarkdown(research?.title??props.workspaceTitle,data.cards,data.network)],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='index.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 const sourceUrl=(id:string,inline=false)=>`/evolver/research-bootstrap/source?${new URLSearchParams({sessionId:props.sessionId,researchId:research?.researchId??'',sourceId:id,...(inline?{inline:'image'}:{})})}`;
 const nodeLabel=(n:StudioNode)=>KINDS[n.kind]??n.kind;
