import { FollowupAdoptionForm } from './FollowupAdoptionForm.tsx';
import { SchedulePanel } from './SchedulePanel.tsx';
import { useEffect, useRef, useState } from 'react';
import type { GeneralResearch } from '../../../../evolver/src/contracts/general-research.ts';
import type { ResearchCycleData } from '../integration/research-cycle-view.ts';
import { newOperationId } from '../redesign/research-actions.ts';
export function GeneralTeamPanel({ general: g, researchId, sessionId, nodeId, refresh, adoptAction, taskDraftId, taskDraftSources }: { general: GeneralResearch; researchId: string; sessionId: string; nodeId: string; refresh: () => Promise<void>; adoptAction(type: string, payload: Record<string, unknown>): Promise<Record<string, unknown> | null>; taskDraftId?: string; taskDraftSources?: string[] }): JSX.Element {
  const [view, setView] = useState<ResearchCycleData | null>(null), [error, setError] = useState(''), [busy, setBusy] = useState(false), [authorized, setAuthorized] = useState(false), [detail, setDetail] = useState<unknown>(null);
  const [sources, setSources] = useState<string[]>(g.ideas[0]?.sourceRefs.length ? g.ideas[0].sourceRefs : g.sources.slice(0, 10).map(s => s.sourceId));
  const [independentConcurrency, setIndependentConcurrency] = useState(false), [selectedRun, setSelectedRun] = useState('');
  const [renewChain, setRenewChain] = useState(false), [renewalReason, setRenewalReason] = useState('');
  useEffect(() => { setAuthorized(false); setRenewChain(false); setIndependentConcurrency(false); }, [nodeId, g.revision]);
  // F04：携带任务草稿时，来源按草稿冻结的版本使用，不允许在启动前隐式换来源。
  useEffect(() => { if (taskDraftSources !== undefined) setSources(taskDraftSources); }, [taskDraftId, taskDraftSources?.join(',')]);
  const request = useRef(0), operation = useRef<{ key: string; id: string } | null>(null);
  const query = new URLSearchParams({ sessionId, researchId, ...(selectedRun ? { runId: selectedRun } : {}) });
  const read = async () => { const r = await fetch(`/evolver/research-cycle?${query}`, { credentials: 'same-origin' }); const body = await r.json(); if (!r.ok) throw new Error(body.message ?? body.error); return body as ResearchCycleData; };
  useEffect(() => { let alive = true; const id = ++request.current; const load = async () => { try { const body = await read(); if (alive && id === request.current) { setView(body); setError(''); } } catch (e) { if (alive) setError(e instanceof Error ? e.message : String(e)); } }; void load(); const timer = window.setInterval(() => void load(), 5000); return () => { alive = false; clearInterval(timer); }; }, [sessionId, researchId, g.revision, selectedRun]);
  const run = view?.runs.find(r => r.runId === (selectedRun || view.research.activeRunId)), active = run && ['queued', 'running', 'waiting_result', 'cancelling'].includes(run.status);
  const visibleSteps = view?.steps.filter(s => s.runId === run?.runId) ?? [];
  const activeRuns = view?.runs.filter(r => ['queued', 'running', 'waiting_result', 'cancelling'].includes(r.status)) ?? [];
  const startBlocked = activeRuns.length > 0 && (!independentConcurrency || activeRuns.length >= 2 || activeRuns.some(r => r.nodeId === nodeId || !r.concurrencyPolicy));
  const action = async (type: 'start_cycle' | 'cancel_cycle' | 'retry_cycle' | 'resume_cycle', stepId?: string) => {
    if (!view || busy) return; setBusy(true); setError('');
    const key = JSON.stringify({ type, sources, nodeId, runId: run?.runId, stepId, renewChain, renewalReason, independentConcurrency, researchRevision: g.revision });
    if (operation.current?.key !== key) operation.current = { key, id: newOperationId('generic-team') };
    try {
      const state = await fetch(`/evolver/research-bootstrap?sessionId=${encodeURIComponent(sessionId)}`, { credentials: 'same-origin' }); const current = await state.json(); if (!state.ok) throw new Error(current.message ?? current.error);
      const currentResearch = current.bootstrap.researches.find((r: { researchId: string }) => r.researchId === researchId);
      if (type !== 'cancel_cycle' && currentResearch?.general?.revision !== g.revision) throw new Error('研究资料已变化，请同步并重新确认本次授权范围。');
      const latest = await read();
      const response = await fetch(`/evolver/research-cycle/actions?sessionId=${encodeURIComponent(sessionId)}`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ type, operationId: operation.current.id, researchId, baseRevision: current.bootstrap.revision, cycleRevision: latest.research.cycleRevision, ...(type === 'start_cycle' ? { authorize: true, ...(taskDraftId !== undefined ? { taskDraftId } : {}), ...(independentConcurrency ? { allowIndependentConcurrency: true } : {}), ...(renewChain ? { renewChain: { reason: renewalReason } } : {}), selectedIdeaId: (() => { const origin = g.graph.nodes.find(n => n.nodeId === nodeId)?.task?.origin; return origin?.kind === 'cycle_decision' ? latest.runs.find(r => r.runId === origin.runId)?.selectedIdeaRef?.ideaId : g.ideas[0]?.ideaId; })(), nodeId, sourceIds: sources } : { runId: run?.runId, ...(type === 'retry_cycle' || type === 'resume_cycle' ? { authorize: true } : {}), ...(stepId ? { stepId } : {}) }) }) });
      const body = await response.json(); if (!response.ok || body.ok !== true) throw new Error(body.reason ?? body.message ?? body.error);
      operation.current = null; setAuthorized(false); setRenewChain(false); setIndependentConcurrency(false); setView(await read()); await refresh();
    } catch (e) { setError(e instanceof Error ? e.message : String(e)); } finally { setBusy(false); }
  };
  const inspect = async (path: string) => { try { const response = await fetch(path, { credentials: 'same-origin' }); const body = await response.json(); if (!response.ok) throw new Error(body.message ?? body.error); setDetail(body); } catch (e) { setError(e instanceof Error ? e.message : String(e)); } };
  return <section className="panel" data-general-team><div className="panel-head"><h2>真实 Agent Team · 已有证据分析</h2><span className="badge">{view?.runtime?.mode ?? '尚未获得执行能力'}</span></div><div className="panel-body stack">
    <SchedulePanel key={researchId} general={g} researchId={researchId} sessionId={sessionId} schedules={view?.schedules ?? []} runtimeAvailable={view?.runtime?.available === true} refresh={async () => { setView(await read()); await refresh(); }} />
    <p className="small muted">冻结 Idea 与已选来源/字典版本；分配原生成员和任务，保存四类结构化产物。只分析已有材料，不启动训练或自动下一轮。</p>
    {view?.runtime?.reason && <p role="status">{view.runtime.reason}</p>}
    <label>查看与停止指定运行<select value={selectedRun} disabled={busy} onChange={e => { setSelectedRun(e.currentTarget.value); setAuthorized(false); }}><option value="">默认活动运行</option>{view?.runs.map(r => <option key={r.runId} value={r.runId}>{r.runId} · {r.status}</option>)}</select></label>
    <label className="flex"><input type="checkbox" style={{ width: 'auto' }} checked={independentConcurrency} disabled={busy} onChange={e => { setIndependentConcurrency(e.currentTarget.checked); setAuthorized(false); }} />明确授权独立节点并发（最多两个活动运行，各自保留尝试与轮数限制）</label>
    <label>本轮来源（最多 10 项，按实际版本分配）<select multiple value={sources} disabled={busy || startBlocked || taskDraftId !== undefined} onChange={e => { setSources([...e.target.selectedOptions].map(o => o.value)); setAuthorized(false); }}>{g.sources.map(s => { const frozenRev = taskDraftId !== undefined ? g.teamTaskDrafts.find(d => d.draftId === taskDraftId)?.sources.find(x => x.sourceId === s.sourceId)?.revision : undefined; return <option key={s.sourceId} value={s.sourceId}>{s.filename} · v{s.revision}{frozenRev !== undefined && frozenRev !== s.revision ? `（草稿冻结 v${frozenRev}，已过期）` : ''} · {s.nature}</option>; })}</select></label>
    {g.requireHumanConfirmation && <label className="flex"><input type="checkbox" style={{ width: 'auto' }} checked={authorized} onChange={e => setAuthorized(e.target.checked)} />确认本轮输入和有限 Team 分析；不授权真实实验或下一轮</label>}
    {g.graph.nodes.find(n => n.nodeId === nodeId)?.task?.origin.kind === 'cycle_decision' && <fieldset disabled={busy || startBlocked}><legend>旧链额度不足时的新授权</legend><label className="flex"><input type="checkbox" style={{ width: 'auto' }} checked={renewChain} onChange={e => { setRenewChain(e.currentTarget.checked); setAuthorized(false); }} />明确按当前研究额度开始新链（旧链消耗保留）</label>{renewChain && <label>新授权理由<textarea value={renewalReason} required maxLength={2000} onChange={e => { setRenewalReason(e.currentTarget.value); setAuthorized(false); }} /></label>}</fieldset>}
    <button className="primary" disabled={busy || startBlocked || !g.graph.nodes.some(n => n.nodeId === nodeId) || !view?.runtime?.available || (g.requireHumanConfirmation && !authorized) || sources.length > 10 || (renewChain && !renewalReason.trim())} onClick={() => void action('start_cycle')}>启动当前节点 Team 分析</button>
    {active && <button disabled={busy} onClick={() => void action('cancel_cycle')}>停止当前循环</button>}
    {run?.status === 'interrupted' && visibleSteps.length === 4 && visibleSteps.every(s => ['pending', 'completed'].includes(s.status)) && <button disabled={busy || !view?.runtime?.available || (g.requireHumanConfirmation && !authorized)} onClick={() => void action('resume_cycle')}>明确恢复未开始的轮次</button>}
    {run?.chain && <p className="small muted">链：{run.chain.rootRunId} · 第 {run.round}/{run.executionPolicy?.maxRounds ?? 1} 轮 · 单角色最多 {run.executionPolicy?.maxAttempts ?? 1} 次 · 冻结截止 {run.executionPolicy?.deadline ?? '未设置'}（失败/取消不退还预约）</p>}
    {run && <p>运行：{run.runId} · {run.status}{run.error && <span className="error"> · 首错：{run.error.message}</span>}</p>}
    {run?.stopHistory?.length ? <details><summary>历史停止记录（{run.stopHistory.length}）</summary><pre>{JSON.stringify(run.stopHistory, null, 2)}</pre></details> : null}{visibleSteps.map(step => <details key={`${step.stepId}-${step.attemptId}`} open={step.status === 'running' || step.status === 'failed'}><summary>{step.role} · {step.status}</summary><p className="small">实际成员：{step.assignedMemberId ?? '未分配'}<br />原生任务：{step.nativeTask?.taskId ?? '未映射'}<br />Attempt：{step.attemptId}<br />等待：{step.blocking.join('、') || '无'}</p>{step.error && <p role="alert" className="error">首错：{step.error.message}</p>}{step.outputRefs.map(ref => <button key={ref.id} onClick={() => void inspect(`/evolver/research-cycle/artifacts?${query}&id=${encodeURIComponent(ref.id)}&sha256=${ref.sha256}`)}>查看 {step.role} 产物</button>)}{step.attemptHistory?.length ? <details><summary>历史 attempts（{step.attemptHistory.length}）</summary><pre>{JSON.stringify(step.attemptHistory, null, 2)}</pre></details> : null}{step.assignedMemberId && <button onClick={() => void inspect(`/evolver/research-cycle/trace?${query}&memberId=${encodeURIComponent(step.assignedMemberId!)}`)}>原生运行记录</button>}{!active && ['failed', 'interrupted', 'cancelled'].includes(step.status) && <button disabled={busy || !view?.runtime?.available || (g.requireHumanConfirmation && !authorized)} onClick={() => void action('retry_cycle', step.stepId)}>新 attempt 重试</button>}</details>)}
    {view?.decisions.map((d, i) => <details key={i}><summary>Reviewer · {d.decision}</summary><p>{d.reason}</p>{d.nextActions?.map(a => <div key={a.actionId}><strong>{a.title}</strong><p>{a.detail}</p>{d.runId && d.decisionRef && <FollowupAdoptionForm researchId={researchId} origin={{ kind: 'cycle_decision', runId: d.runId, decisionRef: d.decisionRef, actionId: a.actionId }} suggestion={`${a.title}：${a.detail}`} disabled={busy} action={adoptAction} />}</div>)}<p className="small muted">后续建议已保存，未自动执行。</p></details>)}
    {!!view?.effectiveGraph.nodes.some(n => n.origin === 'cycle') && <details><summary>已保存的 DAG 增量</summary>{view.effectiveGraph.nodes.filter(n => n.origin === 'cycle').map(n => <p key={n.nodeId}>{n.title} · {n.artifactRef ? '已登记产物' : '未来任务，未执行'}</p>)}</details>}
    {error && <p role="alert" className="error">{error}</p>}{detail !== null && <div><button onClick={() => setDetail(null)}>关闭详情</button><pre style={{ maxHeight: 400, overflow: 'auto', whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>{JSON.stringify(detail, null, 2)}</pre></div>}
  </div></section>;
}
