import { useEffect, useRef, useState, type ReactNode, type FormEvent } from 'react';
import type { GeneralResearch } from '../../../../evolver/src/contracts/general-research.ts';
import type { GeneralKnowledgeEntry } from '../../../../evolver/src/contracts/general-knowledge.ts';
import { WikiContent } from './WikiContent.tsx';
import { WIKI_TYPES } from './WikiGraph.tsx';
export type WikiAction = (type: string, payload: Record<string, unknown>) => Promise<Record<string, unknown> | null>;
export const WIKI_NATURES = { unknown: '未知 / 待核对', hypothesis: '假设', inference: '推断', source_reported: '来源报告' };
export function WikiModal({ title, close, children }: { title: string; close: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDialogElement | null>(null); useEffect(() => { const d = ref.current!; d.showModal(); return () => d.close(); }, []);
  return <dialog ref={ref} className="wiki-dialog" aria-label={title} onCancel={e => { e.preventDefault(); close(); }}><header className="wiki-dialog-head"><h2>{title}</h2><button aria-label="关闭弹窗" onClick={close}>×</button></header>{children}</dialog>;
}
export function WikiEditor({ general: g, entry, kind, save, close }: { general: GeneralResearch; entry?: GeneralKnowledgeEntry; kind: GeneralKnowledgeEntry['kind']; save: WikiAction; close: () => void }) {
  const [dirty, setDirty] = useState(false), [error, setError] = useState(''), [working, setWorking] = useState(false);
  const cancel = () => { if (!dirty || !g.requireHumanConfirmation || window.confirm('丢弃未保存的知识草稿？')) close(); };
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setWorking(true); setError(''); const f = new FormData(e.currentTarget);
    try {
      const { entryId: _id, version: _v, createdAt: _at, ...previous } = entry ?? {} as GeneralKnowledgeEntry;
      const textLines = (name: string) => String(f.get(name) ?? '').split('\n').map(s => s.trim()).filter(Boolean);
      const next = { ...previous, kind, title: String(f.get('title')), category: String(f.get('category')), content: String(f.get('content')), entityType: String(f.get('entityType')), nature: String(f.get('nature')), sourceRefs: f.getAll('sourceRefs'), calculationIds: f.getAll('calculationIds'), nodeIds: f.getAll('nodeIds'), input: String(f.get('input') ?? ''), output: String(f.get('output') ?? ''), conditions: textLines('conditions'), counterEvidence: textLines('counterEvidence'), limitations: textLines('limitations'), parameters: kind === 'method' ? JSON.parse(String(f.get('parameters') || '[]')) : [], operation: kind === 'method' ? String(f.get('operation')) : 'manual', archived: f.get('archived') === 'on' };
      if (entry && (next.content !== entry.content || JSON.stringify(next.sourceRefs) !== JSON.stringify(entry.sourceRefs))) { next.claims = []; next.nature = 'unknown'; next.limitations = [...next.limitations, '正文或来源已人工修改，旧版主张定位不自动继承；请重新核对。']; }
      const target = String(f.get('related') ?? ''), result = await save('save_general_knowledge', { entryId: entry?.entryId ?? null, entry: next, ...(!entry && target ? { initialRelation: { toEntryId: target, kind: 'related', note: '人工关联，不代表证据支持' } } : {}) });
      if (!result) throw new Error('知识未保存，请查看具体错误'); close();
    } catch (e) { setError(String(e)); } finally { setWorking(false); }
  }
  return <WikiModal title={entry ? `编辑知识 v${entry.version}` : '新建知识实体'} close={cancel}><form onSubmit={submit} onChange={() => setDirty(true)}>
    <label>实体名称<input autoFocus name="title" required maxLength={300} defaultValue={entry?.title} /></label><label>实体类型<select name="entityType" defaultValue={entry?.entityType ?? 'concept'}>{Object.entries(WIKI_TYPES).filter(([k]) => k !== 'source').map(([k, t]) => <option key={k} value={k}>{t.label}</option>)}</select></label><label>分类<input name="category" required maxLength={100} defaultValue={entry?.category ?? '未分类'} /></label><label>知识正文<textarea name="content" required rows={8} maxLength={12000} defaultValue={entry?.content} /></label><label>主张性质<select name="nature" defaultValue={entry?.nature ?? 'unknown'}>{Object.entries(WIKI_NATURES).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></label>
    <label>资料依据<select name="sourceRefs" multiple defaultValue={entry?.sourceRefs}>{g.sources.map(s => <option key={s.sourceId} value={s.sourceId} disabled={g.sourceAccess.filter(a => a.sourceId === s.sourceId).at(-1)?.allowed === false}>{s.filename}</option>)}</select></label><label>计算依据<select name="calculationIds" multiple defaultValue={entry?.calculationIds}>{g.calculations.map(c => <option key={c.calculationId} value={c.calculationId}>{c.calculationId}</option>)}</select></label><label>关联研究节点<select name="nodeIds" multiple defaultValue={entry?.nodeIds}>{g.graph.nodes.map(n => <option key={n.nodeId} value={n.nodeId}>{n.title}</option>)}</select></label>
    {(['conditions', 'counterEvidence', 'limitations'] as const).map((key, i) => <label key={key}>{['适用条件', '反证与分歧', '限制与未知'][i]}（每行一项）<textarea name={key} defaultValue={entry?.[key]?.join('\n')} /></label>)}
    {kind === 'method' && <><label>输入<input name="input" defaultValue={entry?.input} /></label><label>输出<input name="output" defaultValue={entry?.output} /></label><label>参数 JSON<textarea name="parameters" defaultValue={JSON.stringify(entry?.parameters ?? [])} /></label><label>执行形式<select name="operation" defaultValue={entry?.operation ?? 'manual'}><option value="manual">人工规程</option><option value="existing_calculation">已有计算</option><option value="external_not_connected">外部执行器未接入</option></select></label></>}
    {!entry && <label>关联到已有知识<select name="related"><option value="">不关联</option>{g.knowledge.filter(e => !e.archived && !g.knowledge.some(n => n.entryId === e.entryId && n.version > e.version)).map(e => <option key={e.entryId} value={e.entryId}>{e.title}</option>)}</select></label>}
    {entry && <label><input type="checkbox" name="archived" defaultChecked={entry.archived} />归档（保留历史与引用）</label>}{error && <p role="alert" className="error">{error}</p>}<footer><button type="button" onClick={cancel}>取消</button><button className="action primary" disabled={working}>保存知识</button></footer>
  </form></WikiModal>;
}
export function WikiTools({ general: g, action, read, select, close, exportOkf, importOkf }: { general: GeneralResearch; action: WikiAction; read: (op: string) => Promise<unknown>; select: (id: string) => void; close: () => void; exportOkf: () => void; importOkf: () => void }) {
  const [goal, setGoal] = useState(''), [sources, setSources] = useState<string[]>([]), [error, setError] = useState(''), [maintenance, setMaintenance] = useState<unknown>(null), [papers, setPapers] = useState<{ paperId: string; title: string; sections: { heading: string; summary: string; quote: string; page: number }[] }[] | null>(null);
  const taskReadable = (t: NonNullable<GeneralResearch['wiki']>['tasks'][number]) => t.sources.every(p => g.sources.some(s => s.sourceId === p.sourceId) && g.sourceAccess.filter(a => a.sourceId === p.sourceId).at(-1)?.allowed !== false);
  const request = async (op: string) => { try { const value = await read(op); if (op === 'papers') setPapers((value as { papers: NonNullable<typeof papers> }).papers); else setMaintenance(value); } catch (e) { setError(String(e)); } };
  return <WikiModal title="知识整理与维护" close={close}><div className="stack"><div className="flex"><button onClick={exportOkf}>导出 OKF 包</button><button onClick={importOkf}>导入 OKF 包</button><button onClick={() => void request('lint')}>检查知识库</button><button onClick={() => void request('papers')}>已有论文 Wiki</button></div><h3>整理资料 / 引用问答</h3><label>允许使用的资料<select multiple aria-label="Wiki 任务来源" value={sources} onChange={e => setSources(Array.from(e.target.selectedOptions, o => o.value))}>{g.sources.filter(s => g.sourceAccess.filter(a => a.sourceId === s.sourceId).at(-1)?.allowed !== false).map(s => <option key={s.sourceId} value={s.sourceId}>{s.filename} v{s.revision}</option>)}</select></label><label>整理目标或问题<textarea aria-label="知识任务目标" value={goal} maxLength={4000} onChange={e => setGoal(e.target.value)} /></label><div className="flex">{(['ingest', 'query'] as const).map(taskKind => <button key={taskKind} disabled={!goal.trim() || !sources.length} onClick={async () => { try { const r = await action('start_general_wiki_task', { taskKind, sourceIds: sources, goal }); if (!r) throw new Error('任务未提交；请查看工作台错误'); } catch (e) { setError(String(e)); } }}>{taskKind === 'ingest' ? '整理所选资料' : '基于依据回答'}</button>)}</div>
    {(g.wiki?.tasks ?? []).map(t => <section key={t.taskId}><h4>{t.goal} · {t.status}</h4>{t.error && <p className="error">{t.error}</p>}{t.result && !taskReadable(t) && <p>任务来源已撤权；缓存回答与引用暂不可读。</p>}{t.result && taskReadable(t) && <WikiContent text={t.result} select={select} />}{(taskReadable(t) ? t.citations ?? [] : []).map((l, i) => <div key={i}>{l.kind === 'text' ? <><blockquote>{l.quote}</blockquote><button className="link" onClick={() => { select('source:' + l.sourceId); close(); }}>查看原文 bytes {l.startByte}–{l.endByte} ↗</button></> : <p>{l.kind === 'table' ? '表格定位 · 第 ' + (l.row + 1) + ' 行' : l.kind === 'pdf' ? 'PDF 原文 · 第 ' + l.page + ' 页：' + l.quote : '已有计算定位 · ' + l.calculationId}</p>}</div>)}{t.status === 'pending' && <button onClick={() => void action('fail_general_wiki_task', { taskId: t.taskId })}>结束本次任务</button>}{t.status === 'completed' && t.kind === 'query' && taskReadable(t) && <button onClick={async () => { if (t.result.length > 12000) { setError('回答超过单页上限，请先拆分，未静默截断'); return; } const r = await action('save_general_knowledge', { entry: { kind: 'wiki', title: t.goal.slice(0, 300), category: '问答整理', content: t.result, nature: 'inference', sourceRefs: t.sources.map(s => s.sourceId), calculationIds: [...new Set((t.citations ?? []).flatMap(l => l.kind === 'calculation' ? [l.calculationId] : []))], nodeIds: [], input: '', output: '', conditions: [], parameters: [], operation: 'manual', archived: false, claims: [{ claimId: 'answer', text: t.goal, nature: 'inference', locators: t.citations ?? [], limitation: '问答归档，推断仍需核对。' }], limitations: ['问答归档，引用与推断仍需核对。'] } }); if (r) { select(String(r.entryId)); close(); } }}>保存回答为知识</button>}</section>)}
    {maintenance !== null && <section><h3>维护发现</h3>{((maintenance as { entries: { entryId: string; title: string; issues: string[]; reasons: string[] }[] }).entries ?? []).map(e => <div key={e.entryId}><button className="link" onClick={() => { select(e.entryId); close(); }}>{e.title}</button>{[...e.issues, ...e.reasons].map((s, i) => <p key={i}>{s}</p>)}</div>)}<p>定位与结构检查不证明科学主张成立。</p></section>}
    {papers?.map(p => <section key={p.paperId}><h3>{p.title}</h3>{p.sections.map((s, i) => <div key={i}><h4>{s.heading}</h4><WikiContent text={s.summary} /><blockquote>{s.quote}</blockquote><small>原文第 {s.page} 页</small></div>)}{!p.sections.length && <p>该论文尚无已发布 Wiki</p>}</section>)}
    <details><summary>Wiki Index</summary>{g.knowledge.filter(e => !e.archived && !g.knowledge.some(n => n.entryId === e.entryId && n.version > e.version)).map(e => <button key={e.entryId} className="linked" onClick={() => { select(e.entryId); close(); }}>{e.title} v{e.version}</button>)}</details><details><summary>Wiki Log</summary>{[...(g.wiki?.events ?? [])].reverse().map((e, i) => <p key={i}>{e.at} · {e.kind} · {e.text}</p>)}</details>{error && <p role="alert" className="error">{error}</p>}
  </div></WikiModal>;
}
